private boolean isInContext(FMFile f) {
    for (FMFile contextFile : new ArrayList<>(activity.getFileOpContext().getSecond())) {
        if (contextFile.getFile().getAbsolutePath().equals(f.getFile().getAbsolutePath())) {
            return true;
        }
    }
    return false;
}

private void removeFromContext(FMFile f) {
    // Remove via the iterator, removing from the list while iterating it with a for-each loop
    // causes a ConcurrentModificationException.
    Iterator<FMFile> iterator = activity.getFileOpContext().getSecond().iterator();
    while (iterator.hasNext()) {
        FMFile contextFile = iterator.next();
        if (contextFile.getFile().getAbsolutePath().equals(f.getFile().getAbsolutePath())) {
            iterator.remove();
        }
    }
}

